-- Articles in the database (phase 17, part 2): the admin dashboard writes them, the site reads the published ones.
-- Privacy rule (binding): nothing here touches journal text, assistant chats, assessment results or mood logs.

create table public.articles (
  id bigint generated always as identity primary key,
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) between 3 and 80),
  title text not null check (char_length(title) between 1 and 150),
  excerpt text not null check (char_length(excerpt) between 1 and 300),
  category text not null check (category in ('فهم المشاعر', 'التوتر والضغط النفسي', 'مهارات التعامل', 'النوم والراحة', 'التأمل الذاتي', 'العادات الصحية', 'الوعي بالإدمان', 'العلاقات', 'طلب المساعدة', 'تغيير العادات')),
  minutes smallint not null check (minutes between 1 and 60),
  -- Only the drawings that ship with the site (the page's security policy blocks images from other hosts).
  image_src text not null check (image_src ~ '^/images/articles/[a-z0-9-]+\.svg$'),
  image_alt text not null check (char_length(image_alt) between 1 and 300),
  idea jsonb not null check (jsonb_typeof(idea) = 'object' and pg_column_size(idea) <= 12000),
  practice jsonb not null check (jsonb_typeof(practice) = 'object' and pg_column_size(practice) <= 12000),
  remember text[] not null check (cardinality(remember) between 1 and 8),
  sources jsonb not null default '[]'::jsonb check (jsonb_typeof(sources) = 'array' and pg_column_size(sources) <= 3000),
  status text not null default 'draft' check (status in ('draft', 'published')),
  sort_order integer not null default 1000,
  -- Specialist review: who reviewed it and when (both or neither). Shown on the article when set.
  reviewed_by text check (reviewed_by is null or char_length(reviewed_by) between 1 and 100),
  reviewed_on date,
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((reviewed_by is null) = (reviewed_on is null))
);

create index articles_status_sort_idx on public.articles (status, sort_order, id);

create trigger articles_set_updated_at
  before update on public.articles
  for each row execute function private.set_updated_at();

alter table public.articles enable row level security;
revoke all on table public.articles from anon, authenticated;
grant select on table public.articles to anon, authenticated;
grant insert (slug, title, excerpt, category, minutes, image_src, image_alt, idea, practice, remember, sources, status, sort_order, reviewed_by, reviewed_on)
  on table public.articles to authenticated;
-- The address (slug) never changes after creation, so shared links keep working.
grant update (title, excerpt, category, minutes, image_src, image_alt, idea, practice, remember, sources, status, sort_order, reviewed_by, reviewed_on)
  on table public.articles to authenticated;
grant delete on table public.articles to authenticated;

create policy "articles_select_public" on public.articles
  for select to anon using (status = 'published');

create policy "articles_select_published_or_admin" on public.articles
  for select to authenticated
  using (status = 'published' or exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())));

create policy "articles_insert_admin" on public.articles
  for insert to authenticated
  with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())));

create policy "articles_update_admin" on public.articles
  for update to authenticated
  using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())))
  with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())));

-- Only drafts can be deleted; a published article is hidden (set back to draft) first.
create policy "articles_delete_admin_drafts" on public.articles
  for delete to authenticated
  using (status = 'draft' and exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())));

-- The twelve articles that were in the code, published as they are today (none has a specialist review yet).
insert into public.articles (slug, title, excerpt, category, minutes, image_src, image_alt, idea, practice, remember, sources, status, sort_order)
select r.slug, r.title, r.excerpt, r.category, r.minutes, r.image_src, r.image_alt, r.idea, r.practice, r.remember, r.sources, 'published', r.sort_order
from jsonb_to_recordset($seed$[{"slug":"naming-feelings","title":"تسمية المشاعر: خطوة أولى لفهم نفسك","excerpt":"حين نعطي شعورنا اسمًا، يصبح التعامل معه أوضح وأقل إرباكًا.","category":"فهم المشاعر","minutes":4,"image_src":"/images/articles/naming-feelings.svg","image_alt":"دفتر مفتوح بجانب وجوه صغيرة بألوان مختلفة تعبّر عن مشاعر متنوعة","idea":{"heading":"ابدأ بالملاحظة، لا بالحكم","paragraphs":["قد نحاول أحيانًا تغيير ما نشعر به بسرعة، لكن البداية الأكثر لطفًا هي أن نلاحظ التجربة كما هي. اسأل نفسك: ما الذي يحدث الآن في جسمي وأفكاري؟ لا تحتاج إلى إجابة مثالية؛ يكفي وصف بسيط وصادق."],"quote":"الهدف ليس التخلص من كل شعور صعب، بل بناء مساحة تساعدك على فهمه والاستجابة له بوعي."},"practice":{"heading":"جرّب خطوة صغيرة اليوم","paragraphs":["اختر لحظة هادئة، وأبعد المشتتات لدقيقتين. اكتب جملة عن الموقف، وجملة عن شعورك، ثم حدّد احتياجًا واحدًا واقعيًا. قد يكون الاحتياج راحة قصيرة، أو حديثًا مع شخص موثوق، أو ترتيب مهمة واحدة فقط."],"exercise":"أكمل العبارة: «ألاحظ الآن أنني…، وربما يساعدني أن…». اكتب أول إجابة تأتيك دون تنقيح."},"remember":["التغيير الصغير المتكرر أكثر واقعية من الاندفاع المؤقت.","التعثّر معلومة تساعدك على تعديل خطتك، وليس حكمًا عليك.","إذا استمر الضيق أو أثّر في حياتك اليومية، فطلب دعم متخصص خطوة شجاعة."],"sources":[],"sort_order":10},{"slug":"calm-space","title":"مساحة هادئة وسط ضغط اليوم","excerpt":"خطوات عملية قصيرة تساعدك على تهدئة إيقاع يوم مزدحم.","category":"التوتر والضغط النفسي","minutes":5,"image_src":"/images/articles/calm-space.svg","image_alt":"ركن هادئ فيه كرسي مريح ونافذة ومصباح ونبتة","idea":{"heading":"الضغط إشارة، وليس عيبًا فيك","paragraphs":["حين تتراكم المهام، يستجيب الجسم بتسارع الأفكار وشد العضلات وصعوبة التركيز. هذه استجابة طبيعية تهدف إلى حمايتك، لكنها تصبح مرهقة إذا استمرت طوال اليوم دون فواصل.","لا يشترط أن تتخلص من كل مصادر الضغط حتى تشعر بتحسن. أحيانًا يكفي أن تصنع فواصل صغيرة تعيد لجسمك إحساس الأمان."],"quote":"دقيقتان من التوقف الواعي قد تغيّران طريقة تعاملك مع الساعة التالية."},"practice":{"heading":"اصنع فاصلًا قصيرًا","paragraphs":["بين مهمة وأخرى، توقف قبل أن تبدأ الجديدة. أرخِ كتفيك، وخذ ثلاثة أنفاس أبطأ من المعتاد، واسأل نفسك: ما أهم شيء واحد الآن؟ ثم ابدأ به وحده."],"exercise":"اكتب قائمة بمهام اليوم، ثم ضع علامة على مهمة واحدة فقط يكفي أن تنجزها اليوم لتشعر أنك تقدمت."},"remember":["الفواصل القصيرة جزء من الإنتاجية، وليست هدرًا للوقت.","ترتيب الأولويات يخفف الإحساس بأن كل شيء عاجل.","إذا صار الضغط مستمرًا ويؤثر في نومك أو علاقاتك، فتحدّث مع مختص."],"sources":[{"title":"القيام بما يهم في أوقات الضغط النفسي","org":"منظمة الصحة العالمية","url":"https://www.who.int/docs/default-source/mental-health/sh-2020-ara.pdf?sfvrsn=880a39b7_2"}],"sort_order":20},{"slug":"mindful-breathing","title":"التنفس الواعي في ثلاث دقائق","excerpt":"تمرين بسيط يمكنك استخدامه عندما تحتاج إلى لحظة توقف.","category":"مهارات التعامل","minutes":6,"image_src":"/images/articles/mindful-breathing.svg","image_alt":"شخص جالس يتنفس بهدوء داخل دوائر متسعة كالموجات","idea":{"heading":"لماذا التنفس؟","paragraphs":["التنفس من الوظائف القليلة التي تحدث تلقائيًا ويمكننا أيضًا توجيهها بإرادتنا. حين نبطئ الزفير قليلًا، نرسل للجسم إشارة بأن اللحظة آمنة، فيهدأ الإيقاع تدريجيًا."],"quote":"لا تحاول أن تتنفس \"بشكل صحيح\"؛ يكفي أن تلاحظ النفس وتمنحه وقتًا أطول قليلًا."},"practice":{"heading":"التمرين خطوة بخطوة","paragraphs":["اجلس في وضع مريح، وضع يدًا على بطنك. خذ شهيقًا هادئًا من الأنف لمدة أربع عدات، ثم زفيرًا أبطأ لمدة ست عدات. كرر ذلك لمدة ثلاث دقائق، وإذا شرد ذهنك فأعده إلى العد بلطف."],"exercise":"جرّب التمرين الآن من صفحة تمارين الاسترخاء، ثم لاحظ: هل تغيّر شيء في كتفيك أو في سرعة أفكارك؟"},"remember":["الزفير الأطول من الشهيق يساعد على التهدئة.","إذا شعرت بدوار، توقف وتنفس بشكل طبيعي.","التمرين أداة مساعدة، ولا يغني عن الدعم المتخصص عند الحاجة."],"sources":[{"title":"التعامل مع الضغوط النفسية","org":"المكتب الإقليمي لمنظمة الصحة العالمية لشرق المتوسط","url":"https://www.emro.who.int/mhps/ar/dealing_with_stress.html"}],"sort_order":30},{"slug":"evening-routine","title":"روتين مسائي يدعم راحتك","excerpt":"تغييرات واقعية تهيّئ جسمك وذهنك للراحة دون مثالية.","category":"النوم والراحة","minutes":7,"image_src":"/images/articles/evening-routine.svg","image_alt":"مساء هادئ بقمر ونجوم وكوب شاي دافئ وكتب","idea":{"heading":"النوم يبدأ قبل السرير","paragraphs":["يحتاج الذهن إلى وقت لينتقل من نشاط النهار إلى هدوء الليل. حين ننتقل مباشرة من الشاشة أو العمل إلى السرير، قد يظل الذهن مشغولًا رغم تعب الجسم.","الروتين المسائي ليس قائمة صارمة، بل إشارات متكررة تخبر جسمك أن وقت الراحة اقترب."],"quote":"روتين بسيط تكرره أفضل من روتين مثالي لا تستطيع الالتزام به."},"practice":{"heading":"ابدأ بثلاث إشارات","paragraphs":["قبل النوم بنصف ساعة: خفّف الإضاءة، وأبعد الهاتف عن متناول يدك، واختر نشاطًا هادئًا واحدًا مثل القراءة الخفيفة أو كتابة سطرين عن يومك."],"exercise":"اختر إشارة واحدة فقط وطبّقها ثلاث ليالٍ متتالية، ثم لاحظ ما الذي تغيّر."},"remember":["ثبات موعد الاستيقاظ يساعد على تنظيم النوم أكثر من موعد النوم وحده.","الليالي المتقطعة تحدث للجميع، ولا تعني فشل الروتين.","إذا استمرت صعوبة النوم لأسابيع، فاستشر طبيبًا أو مختصًا."],"sources":[],"sort_order":40},{"slug":"writing-reflection","title":"لماذا تساعدنا الكتابة على التأمل؟","excerpt":"استخدم الورق لترتيب أفكارك بلا حكم أو ضغط.","category":"التأمل الذاتي","minutes":4,"image_src":"/images/articles/writing-reflection.svg","image_alt":"مكتب عليه ورقة وقلم ومصباح وفقاعة فكرة بقلب","idea":{"heading":"الأفكار المكتوبة أخف","paragraphs":["حين تدور الأفكار في الذهن، تبدو أكبر وأكثر تشابكًا. كتابتها تبطئ إيقاعها وتمنحك مسافة صغيرة لترى ما يحدث بوضوح أكبر."],"quote":"لا تكتب لتنتج نصًا جميلًا، بل لتفهم نفسك قليلًا أكثر."},"practice":{"heading":"خمس دقائق من الكتابة الحرة","paragraphs":["اضبط مؤقتًا لخمس دقائق، واكتب كل ما يخطر ببالك دون توقف أو تصحيح. إذا لم تجد ما تكتبه، اكتب \"لا أعرف ماذا أكتب\" حتى تأتي الفكرة التالية."],"exercise":"بعد انتهاء الدقائق الخمس، اقرأ ما كتبته وضع خطًا تحت جملة واحدة تلفت انتباهك. ماذا تخبرك عن احتياجك الآن؟"},"remember":["مذكراتك مساحة خاصة، ولا يوجد فيها صواب أو خطأ.","الكتابة المنتظمة، ولو قليلًا، أنفع من الكتابة الطويلة المتقطعة.","يمكنك البدء الآن من صفحة مذكراتي."],"sources":[],"sort_order":50},{"slug":"small-habits","title":"عادات صغيرة يمكن الاستمرار عليها","excerpt":"ابدأ بخطوة تناسب يومك بدل مطاردة تغيير كبير ومفاجئ.","category":"العادات الصحية","minutes":5,"image_src":"/images/articles/small-habits.svg","image_alt":"درجات صغيرة متصاعدة عليها علامات إنجاز وتنمو فوقها نبتة","idea":{"heading":"لماذا تفشل البدايات الكبيرة؟","paragraphs":["الحماس في البداية يدفعنا إلى أهداف كبيرة، لكن الأيام المزدحمة والتعب يجعلان الاستمرار صعبًا. حين تتعطل الخطة، نشعر بالإحباط ونتركها كلها.","العادة الصغيرة تنجح لأنها ممكنة حتى في أسوأ أيامك."],"quote":"اجعل البداية سهلة لدرجة يصعب معها أن تقول \"لا\"."},"practice":{"heading":"اربط العادة بما تفعله بالفعل","paragraphs":["اختر شيئًا تفعله يوميًا دون تفكير، مثل شرب القهوة الصباحية، واربط به عادة صغيرة جدًا: كوب ماء، أو دقيقة تمدد، أو سطر في مذكراتك."],"exercise":"أكمل الجملة: «بعد أن… سأقوم بـ… لمدة دقيقة واحدة». ثم جرّبها غدًا."},"remember":["الاستمرار أهم من الحجم في البداية.","نسيان يوم لا يعني البدء من الصفر.","كبّر العادة تدريجيًا فقط عندما تصبح سهلة."],"sources":[],"sort_order":60},{"slug":"understanding-urges","title":"فهم الرغبة الملحّة دون مقاومتها بعنف","excerpt":"تعلّم ملاحظة الرغبة وعبورها بخطوات آمنة وغير وصمية.","category":"الوعي بالإدمان","minutes":6,"image_src":"/images/articles/understanding-urges.svg","image_alt":"موجة عالية ترتفع ثم تهدأ بينما شخص يراقبها من الشاطئ","idea":{"heading":"الرغبة موجة، وللموجة نهاية","paragraphs":["الرغبة الملحّة في سلوك أو مادة ما تشبه الموجة: ترتفع، وتصل إلى ذروتها، ثم تنخفض. محاولة طردها بالقوة قد تجعلها أشد، بينما ملاحظتها بهدوء تساعد على عبورها.","الشعور بالرغبة لا يعني ضعفًا في الشخصية؛ إنه جزء مفهوم من تجربة كثيرين."],"quote":"يمكنك أن تلاحظ الرغبة دون أن تطيعها."},"practice":{"heading":"ركوب الموجة","paragraphs":["حين تأتي الرغبة، سمِّها: «هذه رغبة». لاحظ أين تشعر بها في جسمك وكيف تتغير شدتها. امنح نفسك عشر دقائق قبل أي قرار، واستخدمها في نشاط مختلف مثل المشي أو التنفس أو الحديث مع شخص داعم."],"exercise":"قيّم شدة الرغبة من 1 إلى 10 الآن، ثم بعد عشر دقائق. هل تغيّرت؟"},"remember":["تأجيل القرار دقائق قليلة يمنحك مساحة للاختيار.","معرفة المواقف التي تثير الرغبة تساعدك على الاستعداد لها.","التعافي رحلة تستحق الدعم المتخصص؛ طلب المساعدة قوة وليس ضعفًا."],"sources":[],"sort_order":70},{"slug":"addiction-compassion","title":"الوعي بالإدمان يبدأ بالتعاطف","excerpt":"لغة محترمة ومعلومات هادئة تساعد على الوقاية وطلب الدعم.","category":"الوعي بالإدمان","minutes":7,"image_src":"/images/articles/addiction-compassion.svg","image_alt":"شخص يضع يده بلطف على كتف شخص آخر وفوقهما قلب","idea":{"heading":"الوصم يبعد الناس عن المساعدة","paragraphs":["حين نصف شخصًا بكلمات قاسية، قد يخفي معاناته خوفًا من الحكم عليه. أما اللغة المحترمة فتجعل الحديث ممكنًا، والحديث هو أول باب للدعم.","الإدمان حالة معقدة تتداخل فيها عوامل نفسية واجتماعية وجسدية، وليس مجرد \"قرار خاطئ\"."],"quote":"نقول \"شخص يمر بتجربة إدمان\" بدل أن نختصره في وصف واحد."},"practice":{"heading":"كيف تدعم شخصًا تهتم به؟","paragraphs":["استمع أكثر مما تنصح، وعبّر عن قلقك بلغة \"أنا\" مثل: «أنا قلق عليك وأريد أن أفهم». تجنب التهديد أو اللوم، وشجّعه على التواصل مع مختص دون ضغط."],"exercise":"فكّر في جملة واحدة داعمة يمكنك قولها لشخص يمر بوقت صعب، واكتبها في مذكراتك."},"remember":["التعاطف لا يعني الموافقة على كل سلوك، بل احترام الإنسان.","اعتنِ بنفسك أيضًا وأنت تدعم غيرك.","في حالات الخطر أو الطوارئ، تواصل فورًا مع خدمات الطوارئ أو مختص."],"sources":[],"sort_order":80},{"slug":"stress-and-habits","title":"كيف تؤثر الضغوط في عاداتنا؟","excerpt":"لاحظ الرابط بين المواقف الصعبة والسلوك المتكرر بهدوء.","category":"التوتر والضغط النفسي","minutes":4,"image_src":"/images/articles/stress-and-habits.svg","image_alt":"خط متشابك يتحول إلى مسار منتظم من خطوات صغيرة","idea":{"heading":"العادة قد تكون محاولة للراحة","paragraphs":["حين نشعر بالضغط، نبحث تلقائيًا عن شيء يخفف التوتر بسرعة: تصفّح الهاتف، أو الأكل دون جوع، أو السهر. هذه السلوكيات تمنح راحة مؤقتة، لكنها قد تزيد الإرهاق لاحقًا."],"quote":"فهم وظيفة العادة يساعدك على إيجاد بديل يلبي الاحتياج نفسه."},"practice":{"heading":"تتبع الرابط ليومين","paragraphs":["حين تلاحظ نفسك تكرر سلوكًا لا تريده، دوّن بسرعة: ماذا كان يحدث قبله؟ ماذا شعرت؟ وماذا كنت تحتاج فعلًا؟"],"exercise":"اختر بديلًا واحدًا صغيرًا لاحتياج متكرر، مثل مشي دقيقتين بدل التصفح عند الملل."},"remember":["لوم النفس يزيد الضغط ولا يغيّر العادة.","الفضول تجاه سلوكك أنفع من الحكم عليه.","إذا شعرت أن عادة ما خرجت عن السيطرة، فاطلب دعمًا متخصصًا."],"sources":[{"title":"القيام بما يهم في أوقات الضغط النفسي","org":"منظمة الصحة العالمية","url":"https://www.who.int/docs/default-source/mental-health/sh-2020-ara.pdf?sfvrsn=880a39b7_2"}],"sort_order":90},{"slug":"healthy-boundaries","title":"الحدود الصحية ليست أنانية","excerpt":"طرق واضحة ومحترمة للتعبير عن احتياجاتك في العلاقات.","category":"العلاقات","minutes":5,"image_src":"/images/articles/healthy-boundaries.svg","image_alt":"شخص داخل دائرة منقطة تمثل حدوده، حولها أشخاص آخرون","idea":{"heading":"الحدود تحمي العلاقة","paragraphs":["الحدود هي ما تحتاجه لتبقى مرتاحًا وآمنًا في علاقاتك: وقتك، وطاقتك، وخصوصيتك. حين لا نعبّر عنها، يتراكم الاستياء بصمت ويؤثر في العلاقة نفسها."],"quote":"قول \"لا\" لطلب ما يمكن أن يكون \"نعم\" لصحتك ولعلاقة أكثر صدقًا."},"practice":{"heading":"صيغة بسيطة للتعبير","paragraphs":["جرّب هذه الصيغة: «أشعر بـ… عندما… وأحتاج إلى…». مثل: «أشعر بالإرهاق عندما تأتيني طلبات متأخرة، وأحتاج إلى أن نتفق على موعد مسبق»."],"exercise":"فكّر في موقف واحد تكرر مؤخرًا، واكتب جملة حدود بهذه الصيغة دون أن ترسلها بعد."},"remember":["يمكنك أن تكون لطيفًا وحازمًا في الوقت نفسه.","رد فعل الآخرين على حدودك ليس مسؤوليتك وحدك.","إذا كنت في علاقة تشعر فيها بعدم الأمان، فتواصل مع جهة دعم مختصة."],"sources":[],"sort_order":100},{"slug":"asking-for-support","title":"كيف تطلب الدعم عندما تحتاجه؟","excerpt":"خطوات صغيرة لبدء حديث صادق مع شخص تثق به.","category":"طلب المساعدة","minutes":6,"image_src":"/images/articles/asking-for-support.svg","image_alt":"شخصان يمدّان أيديهما نحو بعضهما وفوقهما فقاعتا حوار","idea":{"heading":"طلب الدعم مهارة يمكن تعلّمها","paragraphs":["كثيرون يترددون في طلب المساعدة خوفًا من أن يكونوا عبئًا. لكن معظم الناس يقدّرون أن يثق بهم أحد، والحديث يخفف الوحدة التي تزيد الضيق."],"quote":"لا تحتاج إلى أن تكون في أسوأ حالاتك حتى تستحق الدعم."},"practice":{"heading":"جهّز بدايتك","paragraphs":["اختر شخصًا تشعر معه بالأمان، ووقتًا هادئًا. يمكنك البدء بجملة بسيطة: «أمرّ بفترة صعبة، وأحتاج أن أتحدث مع أحد». وضّح ما تحتاجه: أن يستمع فقط، أو أن يساعدك في التفكير."],"exercise":"اكتب اسم شخص واحد يمكنك التواصل معه هذا الأسبوع، وجملة البداية التي ستقولها."},"remember":["الدعم قد يأتي من صديق، أو فرد من العائلة، أو مختص.","المختص النفسي يقدم مساحة آمنة وسرية للحديث.","إذا شعرت أنك غير آمن الآن، تواصل فورًا مع خدمات الطوارئ."],"sources":[],"sort_order":110},{"slug":"setbacks-are-not-failure","title":"التعثّر لا يلغي التقدّم","excerpt":"نظرة واقعية للانتكاسات وكيفية العودة بخطة أكثر لطفًا.","category":"تغيير العادات","minutes":7,"image_src":"/images/articles/setbacks-are-not-failure.svg","image_alt":"خط يرتفع مع هبوط صغير ثم يواصل الصعود نحو علم","idea":{"heading":"التغيير ليس خطًا مستقيمًا","paragraphs":["حين نحاول تغيير عادة، نتخيل طريقًا صاعدًا بلا توقف. في الواقع، يتخلل التقدم أيام أصعب وعودة لسلوكيات قديمة. هذا جزء طبيعي من الرحلة، وليس دليلًا على الفشل.","ما تعلمته في الأيام الجيدة لا يختفي بسبب يوم صعب."],"quote":"السؤال الأهم ليس \"لماذا تعثرت؟\" بل \"ما الخطوة التالية الممكنة؟\"."},"practice":{"heading":"العودة بلطف","paragraphs":["بعد التعثر، تجنب جلد الذات. راجع ما حدث بفضول: ما الذي سبق التعثر؟ ما الذي كان سيساعدك؟ ثم عدّل خطتك لتصبح أصغر أو أوضح، وعد إليها اليوم أو غدًا."],"exercise":"اكتب ثلاثة أشياء نجحت فيها خلال الفترة الماضية، مهما كانت صغيرة."},"remember":["كل عودة بعد تعثر تقوّي قدرتك على الاستمرار.","الخطة المرنة أقوى من الخطة المثالية.","إذا تكررت الانتكاسات وأرهقتك، فالدعم المتخصص يساعدك على بناء خطة مناسبة."],"sources":[],"sort_order":120}]$seed$::jsonb) as r(
  slug text, title text, excerpt text, category text, minutes smallint, image_src text, image_alt text,
  idea jsonb, practice jsonb, remember text[], sources jsonb, sort_order integer
);
